"math_port_script_native_hook_budget_overflow_and_recovery"_test=[] {
F f(classes());for(auto kind:{"msubsup","munderover"}){auto*a=dynamic_cast<Probe*>(f.create("probe"));auto*b=f.create("probe");auto*n=create(f,kind,{},children({a,b}));int calls=0;a->callback=[&]{++calls;if(std::string_view(kind)=="msubsup")dynamic_cast<Sub*>(n)->hook({},true,2,false);else dynamic_cast<Under*>(n)->hook({},true,2,false);};bool caught=false;try{if(std::string_view(kind)=="msubsup")dynamic_cast<Sub*>(n)->hook({},true,2,false);else dynamic_cast<Under*>(n)->hook({},true,2,false);}catch(const tr::FactoryError&e){caught=true;expect(bool(e.name=="RangeError"));}expect(caught);expect(bool(calls==512));a->callback={};if(std::string_view(kind)=="msubsup")dynamic_cast<Sub*>(n)->hook({},true,2,false);else dynamic_cast<Under*>(n)->hook({},true,2,false);}
};
